import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"16、【豫】 坤下震上","description":"横渠易说 - 16、【豫】 坤下震上","frontmatter":{"title":"16、【豫】 坤下震上","description":"横渠易说 - 16、【豫】 坤下震上"},"headers":[],"relativePath":"zh/classics/hengqu/018.md","filePath":"zh/classics/hengqu/018.md"}'),l={name:"zh/classics/hengqu/018.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_16、【豫】-坤下震上" tabindex="-1">16、【豫】 坤下震上 <a class="header-anchor" href="#_16、【豫】-坤下震上" aria-label="Permalink to “16、【豫】 坤下震上”">​</a></h1><h3 id="彖曰-豫-刚应而志行-顺以动-豫。豫顺以动-故天地如之-而况建侯行师乎-天地以顺动-故日月不过而四时不忒-圣人以顺动-则刑罚清而民服-豫之时义大矣哉" tabindex="-1">彖曰：豫，刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况建侯行师乎!天地以顺动，故日月不过而四时不忒，圣人以顺动，则刑罚清而民服，豫之时义大矣哉! <a class="header-anchor" href="#彖曰-豫-刚应而志行-顺以动-豫。豫顺以动-故天地如之-而况建侯行师乎-天地以顺动-故日月不过而四时不忒-圣人以顺动-则刑罚清而民服-豫之时义大矣哉" aria-label="Permalink to “彖曰：豫，刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况建侯行师乎!天地以顺动，故日月不过而四时不忒，圣人以顺动，则刑罚清而民服，豫之时义大矣哉!”">​</a></h3><p>上动而下不顺，非建侯行师之利也。</p><h3 id="象曰-雷出地奋-豫-先王以作乐崇德-殷荐之上帝以配祖考。" tabindex="-1">象曰：雷出地奋，豫，先王以作乐崇德，殷荐之上帝以配祖考。 <a class="header-anchor" href="#象曰-雷出地奋-豫-先王以作乐崇德-殷荐之上帝以配祖考。" aria-label="Permalink to “象曰：雷出地奋，豫，先王以作乐崇德，殷荐之上帝以配祖考。”">​</a></h3><p>王者之乐，莫大于是。</p><h3 id="初六-鸣豫-凶。-象曰-初六鸣豫-志穷凶也。" tabindex="-1">初六，鸣豫，凶。 象曰：“初六鸣豫”，志穷凶也。 <a class="header-anchor" href="#初六-鸣豫-凶。-象曰-初六鸣豫-志穷凶也。" aria-label="Permalink to “初六，鸣豫，凶。 象曰：“初六鸣豫”，志穷凶也。”">​</a></h3><p>知几者上交不谄，今得应于上，豫独着闻，终凶之道也。故凡豫之理，莫若安其分，动以义也。</p><h3 id="六二-介于石-不终日-贞吉。-象曰-不终日贞吉-以中正也。" tabindex="-1">六二，介于石，不终日，贞吉。 象曰：“不终日贞吉”，以中正也。 <a class="header-anchor" href="#六二-介于石-不终日-贞吉。-象曰-不终日贞吉-以中正也。" aria-label="Permalink to “六二，介于石，不终日，贞吉。 象曰：“不终日贞吉”，以中正也。”">​</a></h3><h3 id="六三-盱豫-悔-迟有悔。-象曰-盱豫有悔-位不当也。" tabindex="-1">六三，盱豫，悔，迟有悔。 象曰：盱豫有悔，位不当也。 <a class="header-anchor" href="#六三-盱豫-悔-迟有悔。-象曰-盱豫有悔-位不当也。" aria-label="Permalink to “六三，盱豫，悔，迟有悔。 象曰：盱豫有悔，位不当也。”">​</a></h3><h3 id="九四-由豫大有得-勿疑-朋盍簪。-象曰-由豫大有得-志大行也。" tabindex="-1">九四，由豫大有得，勿疑，朋盍簪。 象曰：“由豫大有得”，志大行也。 <a class="header-anchor" href="#九四-由豫大有得-勿疑-朋盍簪。-象曰-由豫大有得-志大行也。" aria-label="Permalink to “九四，由豫大有得，勿疑，朋盍簪。 象曰：“由豫大有得”，志大行也。”">​</a></h3><h3 id="六五-贞疾恒不死。-象曰-六五贞疾-乘刚也-恒不死-中未亡也。" tabindex="-1">六五，贞疾恒不死。 象曰：“六五贞疾”，乘刚也；“恒不死”，中未亡也。 <a class="header-anchor" href="#六五-贞疾恒不死。-象曰-六五贞疾-乘刚也-恒不死-中未亡也。" aria-label="Permalink to “六五，贞疾恒不死。 象曰：“六五贞疾”，乘刚也；“恒不死”，中未亡也。”">​</a></h3><h3 id="上六-冥豫-成有渝-无咎。-象曰-冥豫在上-何可长也" tabindex="-1">上六，冥豫，成有渝，无咎。 象曰：冥豫在上，何可长也! <a class="header-anchor" href="#上六-冥豫-成有渝-无咎。-象曰-冥豫在上-何可长也" aria-label="Permalink to “上六，冥豫，成有渝，无咎。 象曰：冥豫在上，何可长也!”">​</a></h3><p>“不终日贞吉”，言疾正则吉也。六二以阴居阴，独无累于四，故其介如石，虽体柔顺，以其在中而静，何俟终日，必知几而正矣。体顺用中，以阴居阴，坚介如石，故在理则悟，为豫之吉莫甚焉，不以悦豫而流也。</p>',13)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
